/// Desktop's mark for provider `id`, if it ships one.
pub fn named(id: &str) -> Option<&'static Icon> {
    Some(match id {
        "opencode" => &OPENCODE,
        "opencode-go" => &OPENCODE_GO,
        "anthropic" => &ANTHROPIC,
        "openai" => &OPENAI,
        "google" => &GOOGLE,
        "xai" => &XAI,
        "deepseek" => &DEEPSEEK,
        "github-copilot" => &GITHUB_COPILOT,
        "github-models" => &GITHUB_MODELS,
        "amazon-bedrock" => &AMAZON_BEDROCK,
        "azure" => &AZURE,
        "mistral" => &MISTRAL,
        "groq" => &GROQ,
        "cerebras" => &CEREBRAS,
        "moonshotai" => &MOONSHOTAI,
        "zai" => &ZAI,
        "vercel" => &VERCEL,
        "fireworks-ai" => &FIREWORKS_AI,
        "togetherai" => &TOGETHERAI,
        "perplexity" => &PERPLEXITY,
        "synthetic" => &SYNTHETIC,
        _ => return None,
    })
}

/// The providers that have a mark of their own, in `named`.
pub const NAMES: &[&str] = &["opencode", "opencode-go", "anthropic", "openai", "google", "xai", "deepseek", "github-copilot", "github-models", "amazon-bedrock", "azure", "mistral", "groq", "cerebras", "moonshotai", "zai", "vercel", "fireworks-ai", "togetherai", "perplexity", "synthetic"];

/// Desktop's stand-in for a provider with no mark of its own.
pub static FALLBACK: &Icon = &SYNTHETIC;
